   154			output(w, map[string]any{"ok": true}, e)
   155		case "purge":
   156			res, e := s.S.DB.Exec(`WITH removed AS (DELETE FROM jobs WHERE queue_id=$1 AND state IN ('queued','scheduled','retry_wait') RETURNING *) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$2,'purged',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, q["id"], s.Clock.Now())
   157			if e != nil {
   158				fail(w, 500, "database_error", e)
   159				return
   160			}
   161			n, _ := res.RowsAffected()
   162			write(w, 200, map[string]any{"deleted": n})
   163		default:
   164			fail(w, 404, "not_found", "unknown operation")
   165		}
   166	}
   167	func (s *Server) queueStats(w http.ResponseWriter, r *http.Request) {
   168		q, ok := s.queueOrError(w, r)
   169		if !ok {
   170			return
   171		}
   172		v, e := stats.Read(s.S, "queue_id", q["id"], s.Clock.Now())
   173		output(w, v, e)
   174	}
   175	func (s *Server) namespaceStats(w http.ResponseWriter, r *http.Request) {
   176		var id int64
   177		e := s.S.DB.QueryRow(`SELECT id FROM namespaces WHERE name=$1`, r.PathValue("ns")).Scan(&id)
   178		if e != nil {
   179			fail(w, 404, "namespace_not_found", e)
   180			return
   181		}
   182		if id != ident(r).Namespace && !ident(r).Admin {
   183			fail(w, 403, "forbidden", "namespace mismatch")
   184			return
   185		}
   186		v, e := stats.Read(s.S, "namespace_id", id, s.Clock.Now())
   187		output(w, v, e)
   188	}
   189	
   190	func validWebhook(raw string) bool {
   191		if raw == "" {
   192			return true
   193		} // Empty disables notifications for future jobs.
   194		u, e := url.Parse(raw)
   195		if e != nil || u.Hostname() == "" || (u.Scheme != "http" && u.Scheme != "https") || strings.ContainsAny(raw, " \t\r\n") {
   196			return false
   197		}
   198		_, e = http.NewRequest("POST", raw, nil)
   199		return e == nil
   200	}
