 1	package jobs
 2	
 3	import (
 4		"crypto/rand"
 5		"database/sql"
 6		"encoding/hex"
 7		"encoding/json"
 8		"fmt"
 9		"github.com/lib/pq"
10		"queuelet/internal/store"
11		"time"
12	)
13	
14	type Service struct{ S *store.Store }
15	
16	func Token() string { b := make([]byte, 16); rand.Read(b); return hex.EncodeToString(b) }
17	func Backoff(kind string, base, attempt int) time.Duration {
18		if kind == "linear" {
19			return time.Duration(base*attempt) * time.Second
20		}
21		return time.Duration(base) * time.Second * time.Duration(uint64(1)<<uint(attempt-1))
22	}
23	
24	const LeaseOrder = "priority DESC, created_at, id"
25	
26	func (j *Service) Lease(q, w int64, max int, now time.Time) ([]map[string]any, error) {
27		tx, e := j.S.DB.Begin()
28		if e != nil {
29			return nil, e
30		}
31		defer tx.Rollback()
32		var sec int
33		var paused bool
34		if e = tx.QueryRow(`SELECT lease_seconds,paused FROM queues WHERE id=$1`, q).Scan(&sec, &paused); e != nil {
35			return nil, e
36		}
37		if paused {
